{"code":"def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0])
    # identify block lattice: cells whose top-left is non-background and 2x2 uniform
    # separators are dominant grid color; use every 3 starting at 0
    R=(H+1)//3; C=(W+1)//3
    pts={}
    for br in range(R):
      for bc in range(C):
        r=3*br; c=3*bc
        if r+1<H and c+1<W:
          v=a[r][c]
          if v not in (0,7,4) and all(a[r+i][c+j]==v for i in (0,1) for j in (0,1)):
            pts.setdefault(v,[]).append((br,bc))
    for v,ps in pts.items():
      for r in range(R):
        cs=[c for rr,c in ps if rr==r]
        if len(cs)>=2:
          for c in range(min(cs),max(cs)+1):
            for i in (0,1):
              for j in (0,1): a[3*r+i][3*c+j]=v
      for c in range(C):
        rs=[r for r,cc in ps if cc==c]
        if len(rs)>=2:
          for r in range(min(rs),max(rs)+1):
            for i in (0,1):
              for j in (0,1): a[3*r+i][3*c+j]=v
    return a"}

